// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import {ERC20} from "https://github.com/OpenZeppelin/openzeppelin-solidity/contracts/token/ERC20/ERC20.sol";
import {ERC20Votes} from "https://github.com/OpenZeppelin/openzeppelin-solidity/contracts/token/ERC20/extensions/ERC20Votes.sol";
import {AccessControl} from "https://github.com/OpenZeppelin/openzeppelin-solidity/contracts/access/AccessControl.sol";

/**
 * @title EquityTokenization
 * @author [Your Name]
 * @notice This contract enables equity tokenization for a private limited company.
 * It allows the company to issue shares as ERC20 tokens with voting capabilities.
 * The contract implements access control to ensure only authorized entities can perform certain actions.
 * @dev This contract uses OpenZeppelin's ERC20Votes and AccessControl for tokenization and access control.
 */
contract EquityTokenization is ERC20Votes, AccessControl {
    // Mapping of roles to their respective descriptions
    bytes32 public constant MINTER_ROLE = "MINTER_ROLE";
    bytes32 public constant DEFAULT_ADMIN_ROLE = "DEFAULT_ADMIN_ROLE";

    /**
     * @notice Initializes the contract with token details and sets up access control roles.
     * @param name_ The name of the token.
     * @param symbol_ The symbol of the token.
     * @param initialSupply_ The initial supply of tokens.
     * @param companyAddress_ The address of the company with the MINTER_ROLE.
     */
    constructor(
        string memory name_,
        string memory symbol_,
        uint256 initialSupply_,
        address companyAddress_
    ) ERC20(name_, symbol_) {
        // Set the initial supply to the company address
        _mint(companyAddress_, initialSupply_);

        // Grant MINTER_ROLE to the company address
        _grantRole(MINTER_ROLE, companyAddress_);

        // Set the admin role for the company
        _grantRole(DEFAULT_ADMIN_ROLE, companyAddress_);
    }

    /**
     * @notice Mints new shares to a specified address.
     * @param to_ The address to receive the new shares.
     * @param amount_ The number of shares to mint.
     * @dev Only the MINTER_ROLE can call this function.
     */
    function mintShares(address to_, uint256 amount_) public onlyRole(MINTER_ROLE) {
        require(to_ != address(0), "Invalid address");
        require(amount_ > 0, "Amount must be greater than zero");

        _mint(to_, amount_);
        emit SharesMinted(to_, amount_);
    }

    /**
     * @notice Transfers shares from one address to another.
     * @param from_ The address to transfer shares from.
     * @param to_ The address to transfer shares to.
     * @param amount_ The number of shares to transfer.
     * @dev Only authorized addresses can transfer shares.
     */
    function transferShares(address from_, address to_, uint256 amount_) public {
        require(from_ != address(0), "From address cannot be zero");
        require(to_ != address(0), "To address cannot be zero");
        require(amount_ > 0, "Amount must be greater than zero");

        _transfer(from_, to_, amount_);
        emit SharesTransferred(from_, to_, amount_);
    }

    /**
     * @notice Authorizes an address to transfer tokens on behalf of another address.
     * @param sender_ The address to authorize.
     * @param recipient_ The address on whose behalf the sender is authorized.
     */
    function authorize(address sender_, address recipient_) public {
        _authorize(sender_, recipient_);
        emit Authorization(sender_, recipient_);
    }

    /**
     * @notice Revokes the authorization of an address to transfer tokens on behalf of another address.
     * @param sender_ The address to revoke authorization from.
     * @param recipient_ The address on whose behalf the authorization is revoked.
     */
    function revokeAuthorization(address sender_, address recipient_) public {
        _revokeAuthorization(sender_, recipient_);
        emit Revocation(sender_, recipient_);
    }

    /**
     * @notice Burns a specified amount of shares from the caller's balance.
     * @param amount_ The number of shares to burn.
     * @dev Only authorized addresses can burn shares.
     */
    function burnShares(uint256 amount_) public {
        require(amount_ > 0, "Amount must be greater than zero");

        _burn(msg.sender, amount_);
        emit SharesBurned(msg.sender, amount_);
    }

    // Events
    event SharesMinted(address indexed to, uint256 amount);
    event SharesTransferred(address indexed from, address indexed to, uint256 amount);
    event Authorization(address indexed sender, address indexed recipient);
    event Revocation(address indexed sender, address indexed recipient);
    event SharesBurned(address indexed burner, uint256 amount);
}
